ac1-assert-default-direct.cmd:
node - <<'NODE'
const fs=require('fs');
const cache=fs.readFileSync('ui/providers/perps/perps-cache.ts','utf8');
const manager=fs.readFileSync('ui/providers/perps/PerpsStreamManager.ts','utf8');
if (!cache.includes('export function fetchMarketInfos(\n  cacheKey: string,\n  useTerminalApi = false,\n)')) throw new Error('fetchMarketInfos default false not found');
if (!cache.includes("'perpsGetMarkets',\n      [{ useTerminalApi }],")) throw new Error('perpsGetMarkets does not forward useTerminalApi');
if (!manager.includes('private _useTerminalApi = false;')) throw new Error('PerpsStreamManager default terminal flag is not false');
if (!manager.includes("'perpsGetMarketDataWithPrices',\n            [{ useTerminalApi: this._useTerminalApi }],")) throw new Error('market data fallback does not forward manager terminal flag');
NODE

ac2-assert-enabled-terminal.cmd:
node - <<'NODE'
const fs=require('fs');
const selector=fs.readFileSync('ui/selectors/perps/feature-flags.ts','utf8');
const bridge=fs.readFileSync('app/scripts/controllers/perps/perps-stream-bridge.ts','utf8');
const controller=fs.readFileSync('app/scripts/metamask-controller.js','utf8');
if (!selector.includes('remoteFeatureFlags.perpsTerminalBackendEnabled')) throw new Error('selector does not read perpsTerminalBackendEnabled');
if (!selector.includes('isPerpsRemoteConfigSatisfied(')) throw new Error('selector does not use version-gated helper');
if (!bridge.includes('useTerminalApi: this.#isTerminalBackendEnabled(),')) throw new Error('bridge hydration does not call terminal backend callback');
if (!controller.includes("'RemoteFeatureFlagController:getState'")) throw new Error('RemoteFeatureFlagController:getState not delegated');
if (!controller.includes('remoteFeatureFlags?.perpsTerminalBackendEnabled')) throw new Error('metamask-controller does not wire terminal flag to bridge');
NODE

ac8-assert-enabled-proof-scope.cmd:
node - <<'NODE'
const fs=require('fs');
const tests=fs.readFileSync('ui/providers/perps/perps-cache.test.ts','utf8') + fs.readFileSync('ui/providers/perps/PerpsStreamManager.test.ts','utf8') + fs.readFileSync('app/scripts/controllers/perps/perps-stream-bridge.test.ts','utf8') + fs.readFileSync('ui/selectors/perps/feature-flags.test.ts','utf8');
for (const needle of ['useTerminalApi: true', 'isTerminalBackendEnabled: () => true', 'perpsTerminalBackendEnabled']) {
  if (!tests.includes(needle)) throw new Error(`missing enabled proof: ${needle}`);
}
NODE
